// A customer scores a resolved ticket, once. A score of 1 or 2 tells the owning agent.
function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('score must be a whole number from 1 to 5');
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (t.rating_score != null) throw new Error('this ticket already has a rating');
  store.updateTicket(id, { rating_score: score, rated_at: now.toISOString() });
  if (score <= 2 && t.owner_id) notifyAgent(store, t.owner_id, { type: 'low_csat_rating', ticketId: id, score });
  return getMyTicket(store, customer, id);
}
```

