- [ ] **Step 3: Implement the job**

Create `src/jobs/agent-csat-summary.js`:

```js
'use strict';
// Nightly. For each agent, how many ratings their tickets received in the past seven days, and the average score.
const fs = require('node:fs');
const path = require('node:path');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;
const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');

function agentCsatSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const totals = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.owner_id) continue;
    if (now.getTime() - new Date(t.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    const agent = totals.get(t.owner_id) || { agent_id: t.owner_id, ratings_count: 0, total_score: 0 };
    agent.ratings_count += 1;
    agent.total_score += t.rating_score;
    totals.set(t.owner_id, agent);
  }
  const rows = [...totals.values()]
    .map((a) => ({
      agent_id: a.agent_id,
      ratings_count: a.ratings_count,
      average_score: Math.round((a.total_score / a.ratings_count) * 100) / 100,
    }))
    .sort((a, b) => a.agent_id - b.agent_id);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-csat-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows };
}

module.exports = { agentCsatSummary, WINDOW_DAYS };
```

